import os
import subprocess
import re
def get_threshold_a():
    try:
        result = subprocess.run(
            "source /home/Ruby/gauss_env_file && cd $GAUSSLOG/../../cm/cm_server/ && grep datastorage_threshold_value_check cm_server.conf",
            shell=True,
            capture_output=True,
            text=True,
            executable="/bin/bash"
        )
        if result.returncode == 0:
            output = result.stdout.strip()
            match = re.search(r'datastorage_threshold_value_check\s*=\s*(\d+)', output)
            if match:
                return int(match.group(1))
        return None
    except Exception:
        return None
def get_disk_usage_b():
    try:
        with open('/home/Ruby/log/ops_collector.log', 'r') as f:
            lines = f.readlines()
        for line in reversed(lines):
            if 'sys065_disk_usage' in line:
                match = re.search(r"sys065_disk_usage:\{'.*?':\s*([0-9.]+)\}", line)
                if match:
                    return float(match.group(1))
        return None
    except Exception:
        return None
def main():
    threshold_a = get_threshold_a()
    disk_usage_b = get_disk_usage_b()
    if threshold_a is None or disk_usage_b is None:
        print("true",end="")
        return
    if disk_usage_b > 0.9 * threshold_a:
        print("false",end="")
    else:
        print("true",end="")
if __name__ == "__main__":
    main()
